<?php require_once __DIR__.'/../auth.php';require_admin();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('index.php');$id=(int)($_POST['id']??0);$s=$conn->prepare('DELETE FROM students WHERE student_id=? AND role<>\'admin\'');$s->bind_param('i',$id);$s->execute();$deleted=$s->affected_rows;$s->close();log_action($conn,(int)$_SESSION['student_id'],'student_delete','Student id '.$id);set_flash($deleted?'Student deleted.':'Student not found or administrator account cannot be deleted.',$deleted?'success':'error');redirect('index.php');
